package dev.proofcode.control.data;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import dev.proofcode.control.project.ProjectRepository;
import dev.proofcode.control.task.*;
import java.time.*;
import java.security.SecureRandom;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** Approval and the execution ledger are durable before any external mutation. Lock order is always task -> operation. */
@Service
public class DataOperationService {
    private final DataResourceRepository resources;private final DataOperationRepository operations;private final DataSchemaRepository schemas;private final DataAuditRepository audits;private final TaskRepository tasks;private final ProjectRepository projects;private final ObjectMapper json;private final PostgresDataAdapter postgres;private final RedisDataAdapter redis;private final TransactionTemplate tx;
    public DataOperationService(DataResourceRepository resources,DataOperationRepository operations,DataSchemaRepository schemas,DataAuditRepository audits,TaskRepository tasks,ProjectRepository projects,ObjectMapper json,PostgresDataAdapter postgres,RedisDataAdapter redis,PlatformTransactionManager manager){this.resources=resources;this.operations=operations;this.schemas=schemas;this.audits=audits;this.tasks=tasks;this.projects=projects;this.json=json;this.postgres=postgres;this.redis=redis;tx=new TransactionTemplate(manager);tx.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_REQUIRES_NEW);}
    private DataAdapter adapter(DataResource r){return switch(r.provider){case "postgres"->postgres;case "redis"->redis;default->throw DataPolicy.bad("unsupported provider");};}
    @Transactional public DataResource register(UUID project,JsonNode request){
        DataPolicy.fields(request,"name","provider","environment","secretRef","allowedSchema");if(!projects.existsById(project))throw DataPolicy.forbidden();String provider=DataPolicy.required(request,"provider"),env=DataPolicy.required(request,"environment"),secret=DataPolicy.required(request,"secretRef");if(!Set.of("postgres","redis").contains(provider)||!Set.of("dev","staging","production").contains(env)||!secret.matches("[A-Z][A-Z0-9_]{0,79}"))throw DataPolicy.bad("invalid resource configuration");String schema=request.path("allowedSchema").asText("public");DataPolicy.identifier(schema);return resources.save(new DataResource(project,provider,env,secret,json.createArrayNode().add(schema).toString()));
    }
    public List<DataResource> resources(UUID project){if(!projects.existsById(project))throw DataPolicy.forbidden();return resources.findByProjectId(project);}
    public List<DataResource> resourcesForTask(UUID task,int attempt){return resources(current(task,attempt,false).getProjectId());}
    public void requireTaskProject(UUID project,UUID task,int attempt){if(!current(task,attempt,false).getProjectId().equals(project))throw DataPolicy.forbidden();}
    private TaskEntity current(UUID id,int attempt,boolean lock){TaskEntity t=(lock?tasks.lockById(id):tasks.findById(id)).orElseThrow(DataPolicy::forbidden);if(t.getAttempt()!=attempt||Set.of(TaskStatus.SUCCEEDED,TaskStatus.FAILED,TaskStatus.CANCELLED).contains(t.getStatus()))throw DataPolicy.conflict("task attempt is expired or terminal");return t;}
    private DataResource scoped(UUID id,TaskEntity t){DataResource r=resources.findById(id).orElseThrow(DataPolicy::forbidden);if(!r.active||!r.projectId.equals(t.getProjectId()))throw DataPolicy.forbidden();return r;}
    public Map<String,Object> inspectSchema(UUID task,int attempt,UUID resource){TaskEntity t=current(task,attempt,false);DataResource r=scoped(resource,t);JsonNode metadata=adapter(r).schema(r);String canonical=canonical(metadata);String version=DataPolicy.hash(canonical);DataSchemaSnapshot snap=tx.execute(status->schemas.save(new DataSchemaSnapshot(r,version,canonical)));return Map.of("snapshotId",snap.id,"schemaVersion",version,"metadata",metadata);}
    private JsonNode schemaFor(DataResource r,String version){if(r.provider.equals("redis"))return adapter(r).schema(r);DataSchemaSnapshot snapshot=schemas.findFirstByConnectionIdAndSchemaVersionOrderByCreatedAtDesc(r.id,version).orElseThrow(()->DataPolicy.bad("schemaVersion has no project snapshot"));if(!snapshot.projectId.equals(r.projectId))throw DataPolicy.forbidden();return parse(snapshot.metadata);}
    @Transactional public DataOperation plan(UUID task,JsonNode request){
        DataPolicy.fields(request,"resourceId","attempt","schemaVersion","ir","idempotencyKey");int attempt=DataPolicy.integer(request,"attempt",1,Integer.MAX_VALUE,-1);TaskEntity t=current(task,attempt,true);DataResource r=scoped(uuid(request,"resourceId"),t);JsonNode ir=request.get("ir");if(ir==null||!ir.isObject()||ir.toString().length()>131072)throw DataPolicy.bad("bounded IR object required");String schemaVersion=r.provider.equals("redis")?DataPolicy.hash(canonical(adapter(r).schema(r))):DataPolicy.required(request,"schemaVersion");if(request.has("schemaVersion")&&!schemaVersion.equals(request.get("schemaVersion").asText()))throw DataPolicy.conflict("cache schema version differs");String key=DataPolicy.required(request,"idempotencyKey");if(key.length()>200)throw DataPolicy.bad("idempotencyKey is too long");String canonical=canonical(ir);DataAdapter.Compiled compiled=adapter(r).compile(r,schemaFor(r,schemaVersion),ir);String digest=digest(t.getId(),t.getProjectId(),attempt,r,canonical,schemaVersion);var previous=operations.findByTaskIdAndAttemptAndIdempotencyKey(task,attempt,key);if(previous.isPresent()){if(!previous.get().digest.equals(digest))throw DataPolicy.conflict("idempotencyKey belongs to different IR");return previous.get();}DataOperation op=operations.save(new DataOperation(task,t.getProjectId(),attempt,r,canonical,digest,schemaVersion,compiled.preview(),key,compiled.kind()));audit(op,"PLAN_CREATED",Map.of("digest",digest));return op;
    }
    public List<DataOperation> plans(UUID project){return operations.findByProjectIdOrderByCreatedAtDesc(project);}
    public List<DataAudit> audit(UUID project){return audits.findByProjectIdOrderByCreatedAtDesc(project);}
    public DataOperation getForTask(UUID task,int attempt,UUID plan){DataOperation op=operations.findById(plan).orElseThrow(DataPolicy::forbidden);if(!op.taskId.equals(task))throw DataPolicy.forbidden();TaskEntity t=current(task,attempt,false);validate(t,op,attempt,op.digest);return op;}
    /** Called by TaskService inside its existing transaction after it locks the task. Never exposed to runner HTTP. */
    @Transactional public void approveFromTool(UUID taskId,int attempt,String toolName,JsonNode arguments,boolean approved){if(!"data_execute".equals(toolName))return;DataPolicy.fields(arguments,"planId","digest");TaskEntity t=current(taskId,attempt,true);DataOperation op=operations.lockById(uuid(arguments,"planId")).orElseThrow(DataPolicy::forbidden);validate(t,op,attempt,DataPolicy.required(arguments,"digest"));decide(op,approved,false);}
    @Transactional public void approveFromTool(UUID taskId,int attempt,String toolName,String arguments,boolean approved){approveFromTool(taskId,attempt,toolName,parse(arguments),approved);}
    @Transactional public ApprovalResult approve(UUID project,UUID plan,String digest,boolean approved){DataOperation read=operations.findById(plan).orElseThrow(DataPolicy::forbidden);TaskEntity t=current(read.taskId,read.attempt,true);DataOperation op=operations.lockById(plan).orElseThrow(DataPolicy::forbidden);if(!op.projectId.equals(project))throw DataPolicy.forbidden();validate(t,op,op.attempt,digest);String capability=decide(op,approved,true);return new ApprovalResult(op.id,op.status,op.digest,capability,op.capabilityExpiresAt);}
    private String decide(DataOperation op,boolean approved,boolean explicit){if(!op.status.equals("PENDING")){if(!explicit&&op.status.equals(approved?"APPROVED":"DENIED"))return null;throw DataPolicy.conflict("plan has already been decided");}op.status=approved?"APPROVED":"DENIED";op.updatedAt=Instant.now();String cap=null;if(approved){op.capabilityExpiresAt=Instant.now().plusSeconds(300);if(explicit){cap=token();op.capabilityHash=DataPolicy.hash(cap);}}audit(op,approved?"USER_APPROVED":"USER_DENIED",Map.of("digest",op.digest));return cap;}
    public record ApprovalResult(UUID planId,String status,String digest,String capability,Instant expiresAt){}
    public record ExecutionResult(UUID planId,String status,Map<String,Object> result){}
    public ExecutionResult executeApproved(UUID task,int attempt,UUID plan,String digest){return execute(task,null,attempt,plan,digest,null,true);}
    public ExecutionResult executeWithCapability(UUID project,int attempt,UUID plan,String digest,String cap){return execute(null,project,attempt,plan,digest,cap,false);}
    private record Started(DataOperation operation,DataResource resource,boolean repeated){}
    private ExecutionResult execute(UUID task,UUID project,int attempt,UUID plan,String digest,String capability,boolean internal){
        Started started=tx.execute(status->{DataOperation read=operations.findById(plan).orElseThrow(DataPolicy::forbidden);if(task!=null&&!read.taskId.equals(task)||project!=null&&!read.projectId.equals(project))throw DataPolicy.forbidden();TaskEntity t=current(read.taskId,attempt,true);DataOperation op=operations.lockById(plan).orElseThrow(DataPolicy::forbidden);DataResource r=validate(t,op,attempt,digest);
            if(Set.of("COMMITTED","SUCCEEDED","FAILED_ROLLED_BACK","FAILED_PRECONDITION","COMPENSATED","COMPENSATION_CONFLICT").contains(op.status))return new Started(op,r,true);
            if(!op.status.equals("APPROVED"))throw DataPolicy.conflict("operation is unapproved, in flight, or has an unknown outcome");if(op.capabilityExpiresAt==null||!op.capabilityExpiresAt.isAfter(Instant.now()))throw DataPolicy.conflict("approval capability expired");
            String effective=capability;if(internal){effective=token();op.capabilityHash=DataPolicy.hash(effective);}if(effective==null||op.capabilityHash==null||!java.security.MessageDigest.isEqual(op.capabilityHash.getBytes(java.nio.charset.StandardCharsets.UTF_8),DataPolicy.hash(effective).getBytes(java.nio.charset.StandardCharsets.UTF_8)))throw DataPolicy.forbidden();if(op.capabilityUsedAt!=null)throw DataPolicy.conflict("capability already consumed");op.capabilityUsedAt=Instant.now();op.status="EXECUTING";op.updatedAt=Instant.now();audit(op,"EXECUTION_STARTED",Map.of("digest",op.digest));return new Started(op,r,false);});
        DataOperation op=started.operation();DataResource r=started.resource();if(started.repeated())return new ExecutionResult(op.id,op.status,op.resultSummary==null?Map.of():json.convertValue(parse(op.resultSummary),Map.class));DataAdapter a=adapter(r);DataAdapter.Compiled compiled;String snapshot;
        if(op.kind.equals("compensation")){DataAdapter.Outcome outcome;try{if(!r.provider.equals("redis")||op.privateSnapshot==null||!DataPolicy.hash(op.privateSnapshot).equals(parse(op.canonicalIr).path("snapshotHash").asText()))return finish(op.id,new DataAdapter.Outcome("FAILED_PRECONDITION",Map.of("errorCode","COMPENSATION_SNAPSHOT_MISMATCH"),null));outcome=a.compensate(r,op.privateSnapshot);}catch(Exception e){outcome=new DataAdapter.Outcome("COMPENSATION_UNKNOWN",Map.of("errorCode","UNCONFIRMED_COMPENSATION_RESULT"),null);}return finish(op.id,outcome);}
        try{JsonNode schema=schemaFor(r,op.schemaVersion);if(r.provider.equals("postgres")&&!op.schemaVersion.equals(DataPolicy.hash(canonical(a.schema(r)))))throw DataPolicy.conflict("database schema changed after preview");compiled=a.compile(r,schema,parse(op.canonicalIr));snapshot=a.prepare(r,compiled);if(snapshot!=null)tx.executeWithoutResult(s->{DataOperation locked=operations.lockById(op.id).orElseThrow();locked.privateSnapshot=snapshot;audit(locked,"SNAPSHOT_PREPARED",Map.of("snapshotHash",DataPolicy.hash(snapshot)));});}
        catch(Exception e){return finish(op.id,new DataAdapter.Outcome("FAILED_PRECONDITION",Map.of("errorCode","EXECUTION_PRECONDITION_FAILED"),null));}
        DataAdapter.Outcome outcome;try{outcome=a.execute(r,compiled,snapshot);}catch(Exception e){outcome=new DataAdapter.Outcome("COMMIT_UNKNOWN",Map.of("errorCode","UNCONFIRMED_EXTERNAL_RESULT"),snapshot);}return finish(op.id,outcome);
    }
    private DataResource validate(TaskEntity t,DataOperation op,int attempt,String given){if(op.attempt!=attempt||!op.taskId.equals(t.getId())||!op.projectId.equals(t.getProjectId()))throw DataPolicy.forbidden();DataResource r=scoped(op.connectionId,t);String actual=digest(op.taskId,op.projectId,op.attempt,r,op.canonicalIr,op.schemaVersion);if(!op.digest.equals(actual)||!actual.equals(given))throw DataPolicy.conflict("immutable operation digest mismatch");return r;}
    private ExecutionResult finish(UUID id,DataAdapter.Outcome result){tx.executeWithoutResult(s->{DataOperation op=operations.lockById(id).orElseThrow();op.status=result.status();op.updatedAt=Instant.now();if(result.privateSnapshot()!=null)op.privateSnapshot=result.privateSnapshot();Map<String,Object> summary=new LinkedHashMap<>();for(String k:List.of("affectedRows","affectedKeys","returnedRows","truncated","errorCode","beforeHash","beforeTtlMs","afterHash"))if(result.result().containsKey(k))summary.put(k,result.result().get(k));op.resultSummary=string(summary);audit(op,"EXECUTION_FINISHED",summary);});return new ExecutionResult(id,result.status(),result.result());}
    /** Redis compensation is another separately approved operation, not a global database rollback. */
    @Transactional public DataOperation compensationPlan(UUID project,UUID original,String idempotencyKey){if(idempotencyKey==null||idempotencyKey.isBlank()||idempotencyKey.length()>200)throw DataPolicy.bad("bounded idempotencyKey is required");DataOperation old=operations.findById(original).orElseThrow(DataPolicy::forbidden);TaskEntity t=current(old.taskId,old.attempt,true);if(!old.projectId.equals(project))throw DataPolicy.forbidden();DataResource r=scoped(old.connectionId,t);if(!r.provider.equals("redis")||!old.status.equals("COMMITTED")||old.privateSnapshot==null)throw DataPolicy.conflict("only confirmed cache writes have a compensation snapshot");String ir=canonical(json.createObjectNode().put("kind","compensation").put("originalPlanId",old.id.toString()).put("snapshotHash",DataPolicy.hash(old.privateSnapshot)));String dig=digest(old.taskId,project,old.attempt,r,ir,old.schemaVersion);var existing=operations.findByTaskIdAndAttemptAndIdempotencyKey(old.taskId,old.attempt,idempotencyKey);if(existing.isPresent()){if(!existing.get().digest.equals(dig))throw DataPolicy.conflict("idempotencyKey belongs to different operation");return existing.get();}DataOperation op=operations.save(new DataOperation(old.taskId,project,old.attempt,r,ir,dig,old.schemaVersion,"CAS compensation of "+old.id,idempotencyKey,"compensation"));op.privateSnapshot=old.privateSnapshot;audit(op,"COMPENSATION_PLANNED",Map.of("originalPlanId",old.id));return op;}
    public Map<String,Object> explain(UUID task,int attempt,UUID plan,String digest){DataOperation op=getForTask(task,attempt,plan);TaskEntity t=current(task,attempt,false);DataResource r=validate(t,op,attempt,digest);if(!r.provider.equals("postgres"))throw DataPolicy.bad("EXPLAIN is only available for PostgreSQL read queries");return postgres.explain(r,postgres.compile(r,schemaFor(r,op.schemaVersion),parse(op.canonicalIr)));}
    private void audit(DataOperation op,String action,Map<String,?> details){audits.save(new DataAudit(op,action,string(details)));}
    private String digest(UUID task,UUID project,int attempt,DataResource resource,String canonical,String schema){return DataPolicy.hash(task+"\n"+project+"\n"+attempt+"\n"+resource.id+"\n"+resource.provider+"\n"+resource.environment+"\n"+schema+"\n"+canonical);}
    private String token(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
    private UUID uuid(JsonNode n,String k){try{return UUID.fromString(DataPolicy.required(n,k));}catch(IllegalArgumentException e){throw DataPolicy.bad("invalid "+k);}}
    private JsonNode parse(String s){try{return json.readTree(s);}catch(Exception e){throw DataPolicy.bad("invalid JSON");}}
    private String string(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
    private String canonical(JsonNode node){return sorted(node).toString();}
    private JsonNode sorted(JsonNode n){if(n.isObject()){ObjectNode o=json.createObjectNode();List<String> keys=new ArrayList<>();n.fieldNames().forEachRemaining(keys::add);Collections.sort(keys);for(String k:keys)o.set(k,sorted(n.get(k)));return o;}if(n.isArray()){ArrayNode a=json.createArrayNode();n.forEach(v->a.add(sorted(v)));return a;}return n;}
}
